ter croissant at Juniper Coffee\">View pastry</button></article>\n  </section>\n</main>\n<script>\nconst fields=[\"drink\",\"size\",\"milk\",\"qty\"],money=n=>\"$\"+n.toFixed(2);\nfunction update(){const q=Math.max(1,+document.querySelector(\"#qty\").value||1),unit=fields.slice(0,3).reduce((s,id)=>s+(+document.querySelector(\"#\"+id).value),0),sub=unit*q,tax=sub*.08;document.querySelector(\"#subtotal\").textContent=money(sub);document.querySelector(\"#tax\").textContent=money(tax);document.querySelector(\"#total\").textContent=money(sub+tax)}\nfields.forEach(id=>document.querySelector(\"#\"+id).addEventListener(\"input\",update));update();\n</script>"}

